    /* Professional touch: an error boundary keeps one broken section
       from taking down the entire study hub, and reports the failure
       to the console instead of leaving a blank page. */
    class StudyHubErrorBoundary extends React.Component {
      constructor(props) {super(props); this.state = {hasError: false};}
      static getDerivedStateFromError() {return {hasError: true};}
      componentDidCatch(error, info) {console.error("Study Hub render error:", error, info);}
      render() {
        if (this.state.hasError) {
          return (
            <div className="study-error-panel">
              <h2>Something went wrong loading this section.</h2>
              <p>Please refresh the page. If the problem persists, check the browser console for details.</p>
            </div>
          );
        }
        return this.props.children;
      }
    }

    ReactDOM.createRoot(document.getElementById("root")).render(
      <React.StrictMode>
        <StudyHubErrorBoundary>
          <App />
        </StudyHubErrorBoundary>
      </React.StrictMode>
    );
